const height = Number($fromAI('height', 'Customer height in centimeters', 'number'));
const weight = Number($fromAI('weight', 'Customer weight in kilograms', 'number'));
const category = String($fromAI('category', 'Clothing category: ao thun, so mi, quan, dam vay, ao khoac', 'string') || '').toLowerCase();
const gender = String($fromAI('gender', 'Customer gender: nam or nu', 'string') || '').toLowerCase();
const fabric = String($fromAI('fabric', 'Fit or fabric: slimfit, regular, oversize, stretch, denim', 'string') || '').toLowerCase();

if (!height || !weight) {
  return 'Cần thêm chiều cao và cân nặng để tư vấn size chính xác.';
}

let size = 'M';
let note = 'dáng tiêu chuẩn';

if (weight < 48 && height < 165) size = 'S';
else if (weight <= 58 && height <= 170) size = 'M';
else if (weight <= 70 && height <= 178) size = 'L';
else size = 'XL';

if (fabric.includes('oversize') || fabric.includes('oversized')) {
  note = 'dáng oversize nên có thể mặc rộng thoải mái';
} else if (fabric.includes('slim')) {
  note = 'dáng slimfit ôm hơn, nếu thích thoải mái có thể cân nhắc tăng 1 size';
} else if (fabric.includes('stretch')) {
  note = 'chất co giãn nên size đề xuất sẽ vừa vặn hơn';
}

return `Recommended size: ${size}. Reason: chiều cao ${height}cm, cân nặng ${weight}kg, ${category || 'trang phục'}, ${gender || 'không rõ giới tính'}, ${note}.`;

