const inputData = $input.first() ? $input.first().json : {};
const outputText = inputData.output || "";

const setChatFieldsNode = $('Set Chat Fields').first();
const userMessage = setChatFieldsNode.json.chatInput || '';
const sessionId = setChatFieldsNode.json.sessionId || 'default';
const mode = setChatFieldsNode.json.mode || 'guest';

// Dynamic mapper to load correct product details and real images from assets/images
const getProductInfoBySku = (sku) => {
  const prefix = sku.substring(0, 2).toUpperCase();
  const index = parseInt(sku.substring(2)) || 1;

  const catalogTemplate = {
    "TS": {
      "name": "Áo thun Cotton Basic Velura #" + index,
      "price": 220000,
      "promo_price": 180000,
      "image_url": "assets/images/ts_basic.png"
    },
    "SM": {
      "name": "Áo sơ mi lụa Satin Velura #" + index,
      "price": 350000,
      "promo_price": 290000,
      "image_url": "assets/images/sm_lua.png"
    },
    "QN": {
      "name": "Quần Jeans dáng Baggy Denim #" + index,
      "price": 350000,
      "promo_price": 290000,
      "image_url": "assets/images/qn_baggy.png"
    },
    "DV": {
      "name": "Đầm voan tơ dáng dài Velura #" + index,
      "price": 380000,
      "promo_price": 320000,
      "image_url": "assets/images/dv_hoanhi.png"
    },
    "AK": {
      "name": "Áo khoác gió dù 2 lớp Velura #" + index,
      "price": 450000,
      "promo_price": 380000,
      "image_url": "assets/images/ak_gio.png"
    }
  };

  if (catalogTemplate[prefix]) {
    return {
      "sku": sku,
      ...catalogTemplate[prefix]
    };
  }
  return null;
};

// Tìm kiếm tất cả mã sản phẩm được nhắc tới trong phản hồi của AI
const skuRegex = /[A-Z]{2}\d{3}/g;
const foundSkus = outputText.match(skuRegex) || [];
const uniqueSkus = [...new Set(foundSkus)];

const products = [];
uniqueSkus.forEach(sku => {
  const prod = getProductInfoBySku(sku);
  if (prod) {
    products.push(prod);
  }
});

// Predict intent based on Router output
const routerOutput = $('Router – Phân Loại Intent').first().json.output || "";
let intent = "Hỏi đáp chung";
if (routerOutput.includes("CONSULT")) {
  intent = "Gợi ý thời trang";
} else if (routerOutput.includes("PRICING")) {
  intent = "Hỏi giá";
} else if (routerOutput.includes("SIZE")) {
  intent = "Hỏi size";
} else if (routerOutput.includes("POLICY")) {
  intent = "Hỏi chính sách";
}

return [{
  json: {
    text: outputText,
    products: products,
    logData: {
      timestamp: new Date().toISOString(),
      sessionId: sessionId,
      mode: mode,
      userMessage: userMessage,
      botResponse: outputText,
      intent: intent
    }
  }
}];
